import pytest

from tests.conftest import auth_headers


def _payload(user):
    return {
        "category_name": "sample category_name",
    }


@pytest.mark.skip(reason="Needs an existing products row; extend this test with one.")
async def test_category_crud(client, make_user):
    user = await make_user("category_owner")
    headers = auth_headers(user)

    r = await client.post("/categories/", json=_payload(user), headers=headers)
    assert r.status_code == 201, r.text
    item_id = r.json()["id"]

    assert (await client.get(f"/categories/{item_id}", headers=headers)).status_code == 200
    listed = (await client.get("/categories/", headers=headers)).json()
    assert item_id in [row["id"] for row in listed]

    r = await client.patch(f"/categories/{item_id}", json={"category_name": "updated category_name"}, headers=headers)
    assert r.status_code == 200, r.text
    assert r.json()["category_name"] == "updated category_name"

    r = await client.put(f"/categories/{item_id}", json=_payload(user), headers=headers)
    assert r.status_code == 200, r.text

    assert (await client.delete(f"/categories/{item_id}", headers=headers)).status_code == 200
    assert (await client.get(f"/categories/{item_id}", headers=headers)).status_code == 404


async def test_category_requires_login(client):
    assert (await client.get("/categories/")).status_code == 401


